// Offline Natural Earth hydrography build. The embedded geographic snapshot is
// public-domain vector data, not artwork or code from a third-party quiz.
// See docs/world-water-map-sources.md for inventory and source adjustments.
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const zlib = require('node:zlib');
const assert = require('node:assert/strict');
const root = path.resolve(__dirname, '..');
const SOURCE_B64 = '';
const hydro = JSON.parse(zlib.gunzipSync(Buffer.from(SOURCE_B64, 'base64')));
const core = fs.readFileSync(path.join(root, 'assets/geography/core.js'), 'utf8');
function declaration(name) {
  const start = core.search(new RegExp('const ' + name + '\\s*='));
  assert(start >= 0, 'Missing local country geometry: ' + name);
  let quote = null, escaped = false;
  for (let i = start; i < core.length; i++) {
    const c = core[i];
    if (quote) { if (escaped) escaped = false; else if (c === '\\') escaped = true; else if (c === quote) quote = null; }
    else if (c === '"' || c === "'") quote = c;
    else if (c === ';') return core.slice(start, i + 1).replace(/^const/, 'var');
  }
  throw Error('Unterminated country geometry: ' + name);
}
const box = {atob: s => Buffer.from(s, 'base64').toString('binary')};
vm.createContext(box);
for (const name of ['COUNTRY_MAP_FILL_B64', 'COUNTRY_MAP_FILL_NAMES']) vm.runInContext(declaration(name), box);
vm.runInContext(core.slice(core.indexOf('function countryMapDecodeCompactPolygon('), core.indexOf('function countryMapLandData(')), box);
const world = vm.runInContext('countryMapDecodeCompactPolygon(COUNTRY_MAP_FILL_B64, COUNTRY_MAP_FILL_NAMES)', box);
const viewBox = [0, 0, 1000, 590];
const project = ([lon, lat]) => [(lon + 180) / 360 * 1000, (80 - lat) / 138 * 590];
const rounded = value => +value.toFixed(3);
const point = p => p.map(rounded);
function clipRing(input) {
  let ring = input.slice();
  for (const [inside, intersection] of [
    [p => p[0] >= -180, (a,b) => [-180, a[1] + (b[1]-a[1]) * (-180-a[0]) / (b[0]-a[0])]],
    [p => p[0] <= 180, (a,b) => [180, a[1] + (b[1]-a[1]) * (180-a[0]) / (b[0]-a[0])]],
    [p => p[1] >= -58, (a,b) => [a[0] + (b[0]-a[0]) * (-58-a[1]) / (b[1]-a[1]), -58]],
    [p => p[1] <= 80, (a,b) => [a[0] + (b[0]-a[0]) * (80-a[1]) / (b[1]-a[1]), 80]]
  ]) {
    const output = [];
    if (!ring.length) break;
    let a = ring.at(-1), aInside = inside(a);
    for (const b of ring) {
      const bInside = inside(b);
      if (aInside !== bInside) output.push(intersection(a,b));
      if (bInside) output.push(b);
      a = b; aInside = bInside;
    }
    ring = output;
  }
  return ring.length >= 3 ? ring : [];
}
function pathForLine(points, closed = false) {
  if (points.length < (closed ? 3 : 2)) return '';
  return points.map((p,i) => (i ? 'L' : 'M') + point(project(p)).join(' ')).join('') + (closed ? 'Z' : '');
}
function simplifyBackground(points) {
  if(points.length<5)return points;
  const projected=points.map(project), keep=new Uint8Array(points.length);
  keep[0]=keep[points.length-1]=1;
  const stack=[[0,points.length-1]];
  while(stack.length) {
    const [a,b]=stack.pop();let max=.06*.06,k=-1;
    const first=projected[a],last=projected[b],dx=last[0]-first[0],dy=last[1]-first[1],length=dx*dx+dy*dy;
    for(let i=a+1;i<b;i++) {
      const p=projected[i],t=length?Math.max(0,Math.min(1,((p[0]-first[0])*dx+(p[1]-first[1])*dy)/length)):0;
      const d=(p[0]-first[0]-dx*t)**2+(p[1]-first[1]-dy*t)**2;
      if(d>max){max=d;k=i;}
    }
    if(k>=0){keep[k]=1;stack.push([a,k],[k,b]);}
  }
  return points.filter((_,i)=>keep[i]);
}
function pathForPolygons(polygons) { return polygons.map(poly => poly.map(ring => pathForLine(ring,true)).join('')).join(''); }
function midpoint(lines) {
  let longest = [], longestLength = 0;
  for (const line of lines) {
    let length = 0;
    for (let i=1;i<line.length;i++) length += Math.hypot(line[i][0]-line[i-1][0], line[i][1]-line[i-1][1]);
    if (length > longestLength) { longest = line; longestLength = length; }
  }
  let remaining = longestLength / 2;
  for (let i=1;i<longest.length;i++) {
    const a=longest[i-1], b=longest[i], length=Math.hypot(b[0]-a[0],b[1]-a[1]);
    if (length >= remaining) return point(project([a[0]+(b[0]-a[0])*remaining/length, a[1]+(b[1]-a[1])*remaining/length]));
    remaining -= length;
  }
  return point(project(longest[0]));
}
function area(ring) {
  let sum=0;
  for(let i=0,j=ring.length-1;i<ring.length;j=i++) sum += ring[j][0]*ring[i][1]-ring[i][0]*ring[j][1];
  return Math.abs(sum/2);
}
function polygonPoint(polygons) {
  const polygon = polygons.slice().sort((a,b) => area(b[0])-area(a[0]))[0];
  // A scan-line midpoint is inside the actual water polygon, even when its
  // centroid would fall on a large island or outside a narrow crescent lake.
  const outer=polygon[0], minY=Math.min(...outer.map(p=>p[1])), maxY=Math.max(...outer.map(p=>p[1]));
  let chosen=null, widest=-1;
  for(let n=1;n<20;n++) {
    const y=minY+(maxY-minY)*n/20, intersections=[];
    for(const ring of polygon) for(let i=0,j=ring.length-1;i<ring.length;j=i++) {
      const a=ring[j],b=ring[i];
      if((a[1]>y)!==(b[1]>y)) intersections.push(a[0]+(b[0]-a[0])*(y-a[1])/(b[1]-a[1]));
    }
    intersections.sort((a,b)=>a-b);
    for(let i=0;i+1<intersections.length;i+=2) {
      const width=intersections[i+1]-intersections[i];
      if(width>widest) { widest=width; chosen=[(intersections[i]+intersections[i+1])/2,y]; }
    }
  }
  assert(chosen, 'No interior point for lake');
  return point(project(chosen));
}
const background=[];
for(const feature of world.features) {
  if(feature.properties.name==='Antarctica') continue;
  const polygons=feature.geometry.type==='Polygon'?[feature.geometry.coordinates]:feature.geometry.coordinates;
  const rings=[];
  for(const polygon of polygons) for(const ring of polygon) {
    const unwrapped=[]; let previous=ring[0][0];
    for(const p of ring) { let lon=p[0]; while(lon-previous>180)lon-=360;while(lon-previous<-180)lon+=360;unwrapped.push([lon,p[1]]);previous=lon; }
    for(const shift of [-360,0,360]) { const clipped=clipRing(unwrapped.map(p=>[p[0]+shift,p[1]]));if(clipped.length)rings.push(clipped); }
  }
  const d=rings.map(ring=>pathForLine(simplifyBackground(ring),true)).join('');
  if(d)background.push({d,kind:'land'});
}
const rivers=hydro.rivers.map(r=>({n:r.n,en:r.en,d:r.lines.map(l=>pathForLine(l)).join(''),c:midpoint(r.lines),kind:'river',hitWidth:9}));
const lakes=hydro.lakes.map(l=>({n:l.n,en:l.en,d:pathForPolygons(l.polygons),c:polygonPoint(l.polygons),kind:'lake',hitWidth:9,
  marker:l.polygons.reduce((sum,p)=>sum+area(p[0])-p.slice(1).reduce((a,r)=>a+area(r),0),0)*1000/360*590/138<20}));
const lakeContext=hydro.lakes.map(l=>({d:pathForPolygons(l.polygons),kind:'lake'}));
const result={version:1,source:'Natural Earth public hydrography snapshot (2026-10-22); user-supplied MapsforUPSC PDFs as feature inventory. See docs/world-water-map-sources.md.',background:background.concat(lakeContext),regions:{
  rivers:{title:'Verdens elver',en:'World rivers',viewBox,states:rivers},
  lakes:{title:'Verdens innsjøer',en:'World lakes',viewBox,states:lakes}
}};
for(const [id,region] of Object.entries(result.regions)) {
  assert.equal(new Set(region.states.map(s=>s.n)).size,region.states.length, id+' names unique');
  assert.equal(new Set(region.states.map(s=>s.en)).size,region.states.length, id+' English names unique');
  for(const target of region.states) {
    assert(target.d.length>25 && !/NaN|Infinity|undefined/.test(target.d), 'Valid vector '+target.n);
    assert(target.c.every((v,i)=>Number.isFinite(v)&&v>=viewBox[i]&&v<=viewBox[i+2]), 'In-map point '+target.n);
  }
}
assert.equal(rivers.length,49);
assert.equal(lakes.length,33);
const riverBounds=name=>hydro.rivers.find(r=>r.n===name).lines.flat();
assert(Math.min(...riverBounds('Yangtze').map(p=>p[0]))<91 && Math.max(...riverBounds('Yangtze').map(p=>p[0]))>119,'Full Yangtze course, including its differently named upper sections');
assert(Math.min(...riverBounds('Mekong').map(p=>p[0]))<95 && Math.max(...riverBounds('Mekong').map(p=>p[0]))>106,'Full Mekong course, including Lancang and Za');
const destination=path.join(root,'assets/geography/physical-maps/world-water.json');
const output=JSON.stringify(result)+'\n';
if(process.argv.includes('--check')) assert.equal(fs.readFileSync(destination,'utf8'),output,'Rebuild world water maps');
else {fs.mkdirSync(path.dirname(destination),{recursive:true});fs.writeFileSync(destination,output);}
console.log(`World water maps: ${rivers.length} rivers, ${lakes.length} lakes; ${Buffer.byteLength(output)} bytes; offline geometry checks passed.`);
